// Generated by Decentraland Studio. Do not edit: this copy is kept in sync with your editor version.
// The rules of resource nodes: a rock, a tree or a fishing spot that hands its kind to whoever stays beside it
// for a few seconds, runs out after a number of uses and comes back later. The Multiplayer Server decides; the
// clients draw what it published. SDK-free, so the server and the tests run the same code.

/** `left` counts the uses remaining (ignored when the rule's `uses` is 0); `by`/`since` are the one gatherer. */
export interface NodeRow { left: number; by?: string; since?: number; backAt?: number }

export interface HarvestState { nodes: Record<string, NodeRow> }

export interface NodeRule {
  kind: string
  /** ms a player stays beside it for one use */
  ms: number
  /** uses before it runs out; 0 never runs out */
  uses: number
  /** ms from running out to coming back; 0 waits for the next round */
  respawnMs: number
}

export type HarvestEventType = 'gather' | 'empty' | 'back'

export interface HarvestEvent { type: HarvestEventType; node: string; kind: string; player?: string }

export interface StartResult { accepted: boolean; state: HarvestState; message?: string }

export interface TickResult { changed: boolean; state: HarvestState; events: HarvestEvent[] }

export const HARVEST_EVENT_TYPES: HarvestEventType[] = ['gather', 'empty', 'back']

export function freshHarvest(): HarvestState {
  return { nodes: {} }
}

function finite(value: unknown): number | undefined {
  return typeof value === 'number' && Number.isFinite(value) ? value : undefined
}

/** Repairs whatever came off the wire; a node absent from `nodes` is full. */
export function readHarvest(raw: unknown): HarvestState {
  const out = freshHarvest()
  if (typeof raw !== 'object' || raw === null) return out
  const nodes = (raw as Record<string, unknown>).nodes
  if (typeof nodes !== 'object' || nodes === null) return out
  for (const [id, value] of Object.entries(nodes as Record<string, unknown>)) {
    if (typeof value !== 'object' || value === null) continue
    const row = value as Record<string, unknown>
    const left = finite(row.left)
    if (left === undefined) continue
    const read: NodeRow = { left: Math.max(0, Math.floor(left)) }
    const since = finite(row.since)
    if (typeof row.by === 'string' && since !== undefined) {
      read.by = row.by
      read.since = since
    }
    const backAt = finite(row.backAt)
    if (backAt !== undefined) read.backAt = backAt
    out.nodes[id] = read
  }
  return out
}

export function nodeRow(state: HarvestState, id: string, rule: NodeRule): NodeRow {
  return state.nodes[id] ?? { left: rule.uses }
}

/** Ran out and not back yet. A node that never runs out is never empty. */
export function isEmpty(row: NodeRow, rule: NodeRule): boolean {
  return rule.uses > 0 && row.left <= 0
}

/** 0..1 of the current gather, 0 when nobody is gathering. */
export function gatherProgress(row: NodeRow | undefined, rule: NodeRule, now: number): number {
  if (row?.since === undefined) return 0
  if (rule.ms <= 0) return 1
  return Math.min(1, Math.max(0, (now - row.since) / rule.ms))
}

/** "m:ss" until it comes back, rounded up so it never reads 0:00 while still empty. */
export function waitText(ms: number): string {
  const total = Math.max(0, Math.ceil(ms / 1000))
  return `${Math.floor(total / 60)}:${String(total % 60).padStart(2, '0')}`
}

/**
 * The line an empty node shows: `timed` with "{time}" replaced by the wait (appended when it has no
 * marker), or `untimed` when it only comes back with the next round. null while it is not empty.
 */
export function emptyLine(row: NodeRow, rule: NodeRule, now: number, timed: string, untimed: string): string | null {
  if (!isEmpty(row, rule)) return null
  if (row.backAt === undefined) return untimed
  const wait = waitText(row.backAt - now)
  return timed.includes('{time}') ? timed.split('{time}').join(wait) : `${timed} ${wait}`.trim()
}

function withRow(state: HarvestState, id: string, row: NodeRow): HarvestState {
  return { nodes: { ...state.nodes, [id]: row } }
}

function idle(row: NodeRow): NodeRow {
  const next: NodeRow = { left: row.left }
  if (row.backAt !== undefined) next.backAt = row.backAt
  return next
}

/** A player starts gathering. `handsFree` is the carry module's answer: the item lands in an empty hand. */
export function startGather(
  state: HarvestState, id: string, player: string, rule: NodeRule | undefined, now: number, handsFree: boolean
): StartResult {
  if (rule === undefined) return { accepted: false, state }
  const row = nodeRow(state, id, rule)
  if (isEmpty(row, rule)) return { accepted: false, state, message: 'Nothing left here yet' }
  if (row.by === player) return { accepted: true, state }
  if (row.by !== undefined) return { accepted: false, state, message: 'Someone is already here' }
  if (!handsFree) return { accepted: false, state, message: 'Your hands are full' }
  return { accepted: true, state: withRow(state, id, { ...idle(row), by: player, since: now }) }
}

/** The gatherer left the scene: their gather stops, nothing is used. */
export function leaveHarvest(state: HarvestState, player: string): HarvestState {
  let next = state
  for (const [id, row] of Object.entries(state.nodes)) {
    if (row.by === player) next = withRow(next, id, idle(row))
  }
  return next
}

/**
 * One server step. `stays(player, id)` says the gatherer is still beside the node; `give(player, kind)` hands
 * the kind over and answers whether it landed (a hand filled meanwhile refuses it, and then nothing is used).
 */
export function tickHarvest(
  state: HarvestState,
  rules: Record<string, NodeRule>,
  now: number,
  stays: (player: string, id: string) => boolean,
  give: (player: string, kind: string) => boolean
): TickResult {
  let next = state
  let changed = false
  const events: HarvestEvent[] = []
  for (const [id, row] of Object.entries(state.nodes)) {
    const rule = rules[id]
    if (rule === undefined) continue
    if (row.backAt !== undefined && now >= row.backAt) {
      next = withRow(next, id, { left: rule.uses })
      changed = true
      events.push({ type: 'back', node: id, kind: rule.kind })
      continue
    }
    if (row.by === undefined || row.since === undefined) continue
    const player = row.by
    if (!stays(player, id)) {
      next = withRow(next, id, idle(row))
      changed = true
      continue
    }
    if (now - row.since < rule.ms) continue
    changed = true
    if (!give(player, rule.kind)) {
      next = withRow(next, id, idle(row))
      continue
    }
    events.push({ type: 'gather', node: id, kind: rule.kind, player })
    if (rule.uses <= 0) {
      next = withRow(next, id, idle(row))
      continue
    }
    const left = Math.max(0, row.left - 1)
    const done: NodeRow = { left }
    if (left === 0) {
      if (rule.respawnMs > 0) done.backAt = now + rule.respawnMs
      events.push({ type: 'empty', node: id, kind: rule.kind })
    }
    next = withRow(next, id, done)
  }
  return { changed, state: next, events }
}
